fn toward(at: Version, to: Version) -> Version {
	if to > at { at.next() } else { at.prev() }.expect("a version between two versions")
}

pub enum Carrier {
	Wire(Vec<u8>),
	Virtual(crate::custom::Virtual),
}

pub fn convert(
	root: Root,
	from: Version,
	to: Version,
	data: &[u8],
	cx: &mut crate::Session,
) -> crate::pds::convert::Result<Vec<Vec<u8>>> {
	let packets = match crate::custom::virtual_start(root, from, to, data, cx)? {
		Some(carried) => carried,
		None => vec![Carrier::Wire(data.to_vec())],
	};
	carry(root, from, to, packets, cx)
}

pub fn carry(
	root: Root,
	from: Version,
	to: Version,
	mut packets: Vec<Carrier>,
	cx: &mut crate::Session,
) -> crate::pds::convert::Result<Vec<Vec<u8>>> {
	let mut at = from;
	while at != to {
		let next = toward(at, to);
		let mut out = Vec::new();
		for p in packets {
			match p {
				Carrier::Wire(bytes) => {
					match crate::custom::virtual_wire(root, at, next, &bytes, cx)? {
						Some(carried) => out.extend(carried),
						None => out.extend(
							step(root, at, next, &bytes, cx)?
								.into_iter()
								.map(Carrier::Wire),
						),
					}
				}
				Carrier::Virtual(model) => {
					out.extend(crate::custom::virtual_step(root, at, next, model, cx)?)
				}
			}
		}
		packets = out;
		at = next;
	}
	let mut wire = Vec::new();
	for p in packets {
		match p {
			Carrier::Wire(bytes) => wire.push(bytes),
			Carrier::Virtual(model) => {
				wire.extend(crate::custom::virtual_finish(root, to, model, cx)?)
			}
		}
	}
	Ok(wire)
}

